  zz=(v,cc,rr,bb,mm,tt,pp)
  if zz not in par:par[zz]=z;act[zz]=ch;q.append(zz)
print('end',end,'states',len(par))
if end:
 aa=[];zs=[];cur=end
 while par[cur] is not None:aa.append(act[cur]);zs.append(cur);cur=par[cur]
